import{_ as o,a0 as l,w as a,s as d,I as e,x as n,ao as r,a1 as i,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"LFCS 系列第七講：通過 SysVinit、Systemd 和 Upstart 管理系統自啓動進程和服務 | LCTT x X-CMD","titleTemplate":false,"description":"LFCS 系列第七講：通過 SysVinit、Systemd 和 Upstart 管理系統自啓動進程和服務 | LCTT (LFCS) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"LFCS 系列第七講：通過 SysVinit、Systemd 和 Upstart 管理系統自啓動進程和服務 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"LFCS 系列第七講：通過 SysVinit、Systemd 和 Upstart 管理系統自啓動進程和服務 | LCTT (LFCS) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"LFCS/Part 7 - LFCS--Managing System Startup Process and Services SysVinit Systemd and Upstart","title":"LFCS 系列第七講：通過 SysVinit、Systemd 和 Upstart 管理系統自啓動進程和服務","tag":"LFCS","desc":""},"relativePath":"LFCS/Part 7 - LFCS--Managing System Startup Process and Services SysVinit Systemd and Upstart.md","filePath":"[post].md"}'),m={name:"LFCS/Part 7 - LFCS--Managing System Startup Process and Services SysVinit Systemd and Upstart.md"};function u(y,t,f,S,c,g){const s=l("Link");return a(),d("div",null,[t[35]||(t[35]=e("h1",{id:"lfcs-系列第七講-通過-sysvinit、systemd-和-upstart-管理系統自啓動進程和服務",tabindex:"-1"},[n("LFCS 系列第七講：通過 SysVinit、Systemd 和 Upstart 管理系統自啓動進程和服務 "),e("a",{class:"header-anchor",href:"#lfcs-系列第七講-通過-sysvinit、systemd-和-upstart-管理系統自啓動進程和服務","aria-label":"Permalink to “LFCS 系列第七講：通過 SysVinit、Systemd 和 Upstart 管理系統自啓動進程和服務”"},"​")],-1)),t[36]||(t[36]=e("p",null,"幾個月前， Linux 基金會宣佈 LFCS (Linux 基金會認證系統管理員) 認證誕生了，這個令人興奮的新計劃定位於讓來自全球各地的初級到中級的 Linux 系統管理員得到認證。這其中包括維護已經在運行的系統和服務的能力、第一手的問題查找和分析能力、以及決定何時向開發團隊提交問題的能力。",-1)),t[37]||(t[37]=e("p",null,[e("img",{src:"http://www.tecmint.com/wp-content/uploads/2014/10/lfcs-Part-7.png",alt:"Linux Foundation Certified Sysadmin – Part 7"})],-1)),t[38]||(t[38]=e("p",null,[e("em",null,"第七講： Linux 基金會認證系統管理員")],-1)),t[39]||(t[39]=e("p",null,"下面的視頻簡要介紹了 Linux 基金會認證計劃。",-1)),t[40]||(t[40]=e("p",null,"注：youtube 視頻",-1)),t[41]||(t[41]=e("iframe",{width:"720",height:"405",frameborder:"0",allowfullscreen:"allowfullscreen",src:"//www.youtube.com/embed/Y29qZ71Kicg"},null,-1)),t[42]||(t[42]=r(`<p>本講是系列教程中的第七講，在這篇文章中，我們會介紹如何管理 Linux 系統自啓動進程和服務，這是 LFCS 認證考試要求的一部分。</p><h3 id="管理-linux-自啓動進程" tabindex="-1">管理 Linux 自啓動進程 <a class="header-anchor" href="#管理-linux-自啓動進程" aria-label="Permalink to “管理 Linux 自啓動進程”">​</a></h3><p>Linux 系統的啓動程序包括多個階段，每個階段由一個不同的圖示塊表示。下面的圖示簡要總結了啓動過程以及所有包括的主要組件。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Linux-Boot-Process.png" alt="Linux Boot Process"></p><p><em>Linux 啓動過程</em></p><p>當你按下你機器上的電源鍵時，存儲在主板 EEPROM 芯片中的固件初始化 POST(通電自檢) 檢查系統硬件資源的狀態。POST 結束後，固件會搜索並加載位於第一塊可用磁盤上的 MBR 或 EFI 分區的第一階段引導程序，並把控制權交給引導程序。</p><h4 id="mbr-方式" tabindex="-1">MBR 方式 <a class="header-anchor" href="#mbr-方式" aria-label="Permalink to “MBR 方式”">​</a></h4><p>MBR 是位於 BIOS 設置中標記為可啓動磁盤上的第一個扇區，大小是 512 個字節。</p><ul><li>前面 446 個字節：包括可執行代碼和錯誤信息文本的引導程序</li><li>接下來的 64 個字節：四個分區（主分區或擴展分區）中每個分區一條記錄的分區表。其中，每條記錄標示了每個一個分區的狀態（是否活躍）、大小以及開始和結束扇區。</li><li>最後 2 個字節： MBR 有效性檢查的魔法數。</li></ul><p>下面的命令對 MBR 進行備份（在本例中，/dev/sda 是第一塊硬盤）。結果文件 mbr.bkp 在分區表被破壞、例如系統不可引導時能排上用場。</p><p>當然，為了後面需要的時候能使用它，我們需要把它保存到別的地方（例如一個 USB 設備）。該文件能幫助我們重新恢復 MBR，這隻在我們操作過程中沒有改變硬盤驅動佈局時才有效。</p><p><strong>備份 MBR</strong></p><pre><code># dd if=/dev/sda of=mbr.bkp bs=512 count=1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Backup-MBR-in-Linux.png" alt="Backup MBR in Linux"></p><p><em>在 Linux 中備份 MBR</em></p><p><strong>恢復 MBR</strong></p><pre><code># dd if=mbr.bkp of=/dev/sda bs=512 count=1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Restore-MBR-in-Linux.png" alt="Restore MBR in Linux"></p><p><em>在 Linux 中恢復 MBR</em></p><h4 id="efi-uefi-方式" tabindex="-1">EFI/UEFI 方式 <a class="header-anchor" href="#efi-uefi-方式" aria-label="Permalink to “EFI/UEFI 方式”">​</a></h4><p>對於使用 EFI/UEFI 方式的系統， UEFI 固件讀取它的設置來決定從哪裏啓動哪個 UEFI 應用。（例如， EFI 分區位於哪塊磁盤或分區。</p><p>接下來，加載並運行第二階段引導程序(又名引導管理器)。GRUB[GRand Unified Boot] 是 Linux 中最常使用的引導管理器。今天大部分使用的系統中都能找到它兩個中的其中一個版本。</p><ul><li>GRUB 有效配置文件： /boot/grub/menu.lst（舊發行版， EFI/UEFI 固件不支持）。</li><li>GRUB2 配置文件： 通常是 /etc/default/grub。</li></ul><p>儘管 LFCS 考試目標沒有明確要求瞭解 GRUB 內部知識，但如果你足夠大膽並且不怕把你的系統搞亂（為了以防萬一，你可以先在虛擬機上進行嘗試）你可以運行：</p><pre><code># update-grub
</code></pre><p>為了使更改生效，你需要以 root 用户修改 GRUB 的配置。</p><p>首先， GRUB 加載默認的內核以及 initrd 或 initramfs 鏡像。補充一句，initrd 或者 initramfs 幫助完成硬件檢測、內核模組加載、以及發現掛載根目錄文件系統需要的設備。</p><p>一旦真正的根目錄文件系統啓動，為了顯示用户界面，內核就會執行系統和服務管理器（init 或 systemd，進程號 PID 一般為 1）開始普通用户態的引導程序。</p><p>init 和 systemd 都是管理其它守護進程的守護進程（後台進程），它們總是最先啓動（系統引導時），最後結束（系統關閉時）。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/systemd-and-init.png" alt="Systemd and Init"></p><p><em>Systemd 和 Init</em></p><h3 id="自啓動服務-sysvinit" tabindex="-1">自啓動服務(SysVinit) <a class="header-anchor" href="#自啓動服務-sysvinit" aria-label="Permalink to “自啓動服務(SysVinit)”">​</a></h3><p>Linux 中運行等級通過控制運行哪些服務來以不同方式使用系統。換句話説，運行等級控制着當前執行狀態下可以完成什麼任務（以及什麼不能完成）。</p><p>傳統上，這個啓動過程是基於起源於 System V Unix 的形式，通過執行腳本啓動或者停止服務從而使機器進入指定的運行等級(換句話説，是一個不同的系統運行模式)。</p><p>在每個運行等級中，獨立服務可以設置為運行、或者在運行時關閉。一些主流發行版的最新版本中，已經移除了標準的 System V，而用一個稱為 systemd（表示系統守護進程）的新服務和系統管理器代替，但為了兼容性，通常也支持 sysv 命令。這意味着你可以在基於 systemd 的發行版中運行大部分有名的 sysv 初始化工具。</p>`,35)),e("ul",null,[e("li",null,[t[1]||(t[1]=n("推薦閲讀： ",-1)),i(s,{href:"http://www.tecmint.com/systemd-replaces-init-in-linux/"},{default:p(()=>[...t[0]||(t[0]=[n("Linux 為什麼用 ‘systemd’ 代替 ‘init’",-1)])]),_:1})])]),t[43]||(t[43]=r(`<p>除了啓動系統進程，init 還會查看 /etc/inittab 來決定進入哪個運行等級。</p><div class="table-wrap"><table><thead><tr><th>Runlevel</th><th>Description</th></tr></thead><tbody><tr><td>0</td><td>停止系統。運行等級 0 是一個用於快速關閉系統的特殊過渡狀態。</td></tr><tr><td>1</td><td>別名為 s 或 S，這個運行等級有時候也稱為維護模式。在這個運行等級啓動的服務由於發行版不同而不同。通常用於正常系統操作損壞時低級別的系統維護。</td></tr><tr><td>2</td><td>多用户。在 Debian 系統及其衍生版中，這是默認的運行等級，還包括了一個圖形化登錄（如果有的話）。在基於紅帽的系統中，這是沒有網絡的多用户模式。</td></tr><tr><td>3</td><td>在基於紅帽的系統中，這是默認的多用户模式，運行除了圖形化環境以外的所有東西。基於 Debian 的系統中通常不會使用這個運行等級以及等級 4 和 5。</td></tr><tr><td>4</td><td>通常默認情況下不使用，可用於自定製。</td></tr><tr><td>5</td><td>基於紅帽的系統中，支持 GUI 登錄的完全多用户模式。這個運行等級和等級 3 類似，但是有可用的 GUI 登錄。</td></tr><tr><td>6</td><td>重啓系統。</td></tr></tbody></table></div><p>要在運行等級之間切換，我們只需要使用 init 命令更改運行等級：init N（其中 N 是上面列出的一個運行等級）。 請注意這並不是運行中的系統切換運行等級的推薦方式，因為它不會給已經登錄的用户發送警告（因而導致他們丟失工作以及進程異常終結）。</p><p>相反，應該用 shutdown 命令重啓系統（它首先發送警告信息給所有已經登錄的用户，並鎖住任何新的登錄；然後再給 init 發送信號切換運行等級）但是，首先要在 /etc/inittab 文件中設置好默認的運行等級（系統引導到的等級）。</p><p>因為這個原因，按照下面的步驟切當地切換運行等級。以 root 用户在 /etc/inittab 中查找下面的行。</p><pre><code>id:2:initdefault:
</code></pre>`,6)),e("p",null,[t[3]||(t[3]=n("並用你喜歡的文本編輯器，例如 vim（本系列的 ",-1)),i(s,{href:"https://linux.cn/article-7165-1.html"},{default:p(()=>[...t[2]||(t[2]=[n("LFCS 系列第二講：如何安裝和使用純文本編輯器 vi/vim",-1)])]),_:1}),t[4]||(t[4]=n("），更改數字 2 為想要的運行等級。",-1))]),t[44]||(t[44]=e("p",null,"然後，以 root 用户執行",-1)),t[45]||(t[45]=e("pre",null,[e("code",null,`# shutdown -r now
`)],-1)),t[46]||(t[46]=e("p",null,"最後一個命令會重啓系統，並使它在下一次引導時進入指定的運行等級，並會執行保存在 /etc/rc[runlevel].d 目錄中的腳本以決定應該啓動什麼服務、不應該啓動什麼服務。例如，在下面的系統中運行等級 2。",-1)),t[47]||(t[47]=e("p",null,[e("img",{src:"http://www.tecmint.com/wp-content/uploads/2014/10/Change-Runlevels-in-Linux.jpeg",alt:"Change Runlevels in Linux"})],-1)),t[48]||(t[48]=e("p",null,[e("em",null,"在 Linux 中更改運行等級")],-1)),t[49]||(t[49]=e("h4",{id:"使用-chkconfig-管理服務",tabindex:"-1"},[n("使用 chkconfig 管理服務 "),e("a",{class:"header-anchor",href:"#使用-chkconfig-管理服務","aria-label":"Permalink to “使用 chkconfig 管理服務”"},"​")],-1)),e("p",null,[t[6]||(t[6]=n("為了在啓動時啓動或者停用系統服務，我們可以在 CentOS / openSUSE 中使用 ",-1)),i(s,{href:"http://www.tecmint.com/chkconfig-command-examples/"},{default:p(()=>[...t[5]||(t[5]=[n("chkconfig 命令",-1)])]),_:1}),t[7]||(t[7]=n("，在 Debian 及其衍生版中使用 sysv-rc-conf 命令。這個工具還能告訴我們對於一個指定的運行等級預先配置的狀態是什麼。",-1))]),e("ul",null,[e("li",null,[t[9]||(t[9]=n("推薦閲讀： ",-1)),i(s,{href:"http://www.tecmint.com/remove-unwanted-services-from-linux/"},{default:p(()=>[...t[8]||(t[8]=[n("如何在 Linux 中停止和停用不想要的服務",-1)])]),_:1})])]),t[50]||(t[50]=r(`<p>列出某個服務的運行等級配置。</p><pre><code># chkconfig --list [service name]
# chkconfig --list postfix
# chkconfig --list mysqld
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Listing-Runlevel-Configuration.png" alt="Listing Runlevel Configuration"></p><p><em>列出運行等級配置</em></p><p>從上圖中我們可以看出，當系統進入運行等級 2 到 5 的時候就會啓動 postfix，而默認情況下運行等級 2 到 4 時會運行 mysqld。現在假設我們並不希望如此。</p><p>例如，我們希望運行等級為 5 時也啓動 mysqld，運行等級為 4 或 5 時關閉 postfix。下面分別針對兩種情況進行設置（以 root 用户執行以下命令）。</p><p><strong>為特定運行等級啓用服務</strong></p><pre><code># chkconfig --level [level(s)] service on
# chkconfig --level 5 mysqld on
</code></pre><p><strong>為特定運行等級停用服務</strong></p><pre><code># chkconfig --level [level(s)] service off
# chkconfig --level 45 postfix off
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Enable-Disable-Services.png" alt="在 Linux 中啓用/停用服務Enable Disable Services in Linux"></p><p><em>啓用/停用服務</em></p><p>我們在基於 Debian 的系統中使用 sysv-rc-conf 完成類似任務。</p><h4 id="使用-sysv-rc-conf-管理服務" tabindex="-1">使用 sysv-rc-conf 管理服務 <a class="header-anchor" href="#使用-sysv-rc-conf-管理服務" aria-label="Permalink to “使用 sysv-rc-conf 管理服務”">​</a></h4><p>配置服務自動啓動時進入指定運行等級，同時禁止啓動時進入其它運行等級。</p><ol><li><p>我們可以用下面的命令查看啓動 mdadm 時的運行等級。</p><pre><code> # ls -l /etc/rc[0-6].d | grep -E &#39;rc[0-6]|mdadm&#39;
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Check-Service-Runlevel.png" alt="查看運行中服務的運行等級Check Runlevel of Service Running"></p><p><em>查看運行中服務的運行等級</em></p></li><li><p>我們使用 sysv-rc-conf 設置防止 mdadm 在運行等級2 之外的其它等級啓動。只需根據需要（你可以使用上下左右按鍵）選中或取消選中（通過空格鍵）。</p><pre><code> # sysv-rc-conf
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/SysV-Runlevel-Config.png" alt="Sysv 運行等級配置SysV Runlevel Config"></p><p><em>Sysv 運行等級配置</em></p><p>然後輸入 q 退出。</p></li><li><p>重啓系統並從步驟 1 開始再操作一遍。</p><pre><code> # ls -l /etc/rc[0-6].d | grep -E &#39;rc[0-6]|mdadm&#39;
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Verify-Service-Runlevel.png" alt="驗證服務運行等級Verify Service Runlevel"></p><p><em>驗證服務運行等級</em></p><p>從上圖中我們可以看出 mdadm 配置為只在運行等級 2 上啓動。</p></li></ol><h3 id="那關於-systemd-呢" tabindex="-1">那關於 systemd 呢？ <a class="header-anchor" href="#那關於-systemd-呢" aria-label="Permalink to “那關於 systemd 呢？”">​</a></h3><p>systemd 是另外一個被多種主流 Linux 發行版採用的服務和系統管理器。它的目標是允許系統啓動時多個任務儘可能並行（而 sysvinit 並非如此，sysvinit 一般比較慢，因為它每次只啓動一個進程，而且會檢查彼此之間是否有依賴，在啓動其它服務之前還要等待守護進程啓動），充當運行中系統動態資源管理的角色。</p><p>因此，服務只在需要的時候啓動，而不是系統啓動時毫無緣由地啓動（為了防止消耗系統資源）。</p><p>要查看你係統中運行的原生 systemd 服務和 Sysv 服務，可以用以下的命令。</p><pre><code># systemctl
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Check-All-Running-Processes.png" alt="在 Linux 中查看運行中的進程Check All Running Processes in Linux"></p><p><em>查看運行中的進程</em></p><p>LOAD 一列顯示了單元（UNIT 列，顯示服務或者由 systemd 維護的其它進程）是否正確加載，ACTIVE 和 SUB 列則顯示了該單元當前的狀態。</p><p><strong>顯示服務當前狀態的信息</strong></p><p>當 ACTIVE 列顯示某個單元狀態並非活躍時，我們可以使用以下命令查看具體原因。</p><pre><code># systemctl status [unit]
</code></pre><p>例如，上圖中 media-samba.mount 處於失敗狀態。我們可以運行：</p><pre><code># systemctl status media-samba.mount
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Check-Service-Status.png" alt="查看 Linux 服務狀態Check Linux Service Status"></p><p><em>查看服務狀態</em></p>`,31)),e("p",null,[t[11]||(t[11]=n("我們可以看到 media-samba.mount 失敗的原因是 host dev1 上的掛載進程無法找到 ",-1)),i(s,{href:"//192.168.0.10/gacanepa"},{default:p(()=>[...t[10]||(t[10]=[n("//192.168.0.10/gacanepa",-1)])]),_:1}),t[12]||(t[12]=n(" 上的共享網絡。",-1))]),t[51]||(t[51]=e("h3",{id:"啓動或停止服務",tabindex:"-1"},[n("啓動或停止服務 "),e("a",{class:"header-anchor",href:"#啓動或停止服務","aria-label":"Permalink to “啓動或停止服務”"},"​")],-1)),e("p",null,[t[14]||(t[14]=n("一旦 ",-1)),i(s,{href:"//192.168.0.10/gacanepa"},{default:p(()=>[...t[13]||(t[13]=[n("//192.168.0.10/gacanepa",-1)])]),_:1}),t[15]||(t[15]=n(" 上的共享網絡可用，我們可以再來嘗試啓動、停止以及重啓 media-samba.mount 單元。執行每次操作之後，我們都執行 systemctl stats media-samba.mout 來查看它的狀態。",-1))]),t[52]||(t[52]=r(`<pre><code># systemctl start media-samba.mount
# systemctl status media-samba.mount
# systemctl stop media-samba.mount
# systemctl restart media-samba.mount
# systemctl status media-samba.mount
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Starting-Stoping-Service.jpeg" alt="啓動停止服務"></p><p><em>啓動停止服務</em></p><p><strong>啓用或停用某服務隨系統啓動</strong></p><p>使用 systemd 你可以在系統啓動時啓用或停用某服務</p><pre><code># systemctl enable [service] 		# 啓用服務
# systemctl disable [service] 		# 阻止服務隨系統啓動
</code></pre><p>啓用或停用某服務隨系統啓動包括在 /etc/systemd/system/multi-user.target.wants 目錄添加或者刪除符號鏈接。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Enabling-Disabling-Services.jpeg" alt="啓用或停用服務"></p><p><em>啓用或停用服務</em></p><p>你也可以用下面的命令查看某個服務的當前狀態（啓用或者停用）。</p><pre><code># systemctl is-enabled [service]
</code></pre><p>例如，</p><pre><code># systemctl is-enabled postfix.service
</code></pre><p>另外，你可以用下面的命令重啓或者關閉系統。</p><pre><code># systemctl reboot
# systemctl shutdown
</code></pre><h3 id="upstart" tabindex="-1">Upstart <a class="header-anchor" href="#upstart" aria-label="Permalink to “Upstart”">​</a></h3><p>基於事件的 Upstart 是 /sbin/init 守護進程的替代品，它僅為在需要那些服務的時候啓動服務而生，（或者當它們在運行時管理它們），以及處理發生的實踐，因此 Upstart 優於基於依賴的 sysvinit 系統。</p><p>一開始它是為 Ubuntu 發行版開發的，但在紅帽企業版 Linux 6.0 中得到使用。儘管希望它能在所有 Linux 發行版中替代 sysvinit，但它已經被 systemd 超越。2014 年 2 月 14 日，Mark Shuttleworth（Canonical Ltd. 創建者）發佈聲明之後的 Ubuntu 發行版採用 systemd 作為默認初始化守護進程。</p><p>由於 Sysv 啓動腳本已經流行很長時間了，很多軟件包中都包括了 Sysv 啓動腳本。為了兼容這些軟件， Upstart 提供了兼容模式：它可以運行保存在常用位置（/etc/rc.d/rc?.d, /etc/init.d/rc?.d, /etc/rc?.d或其它類似的位置）的Sysv 啓動腳本。因此，如果我們安裝了一個還沒有 Upstart 配置腳本的軟件，仍然可以用原來的方式啓動它。</p>`,19)),e("p",null,[t[17]||(t[17]=n("另外，如果我們還安裝了類似 ",-1)),i(s,{href:"http://www.tecmint.com/chkconfig-command-examples/"},{default:p(()=>[...t[16]||(t[16]=[n("chkconfig",-1)])]),_:1}),t[18]||(t[18]=n(" 的工具，你還可以和在基於 sysvinit 的系統中一樣用它們管理基於 Sysv 的服務。",-1))]),t[53]||(t[53]=r(`<p>Upstart 腳本除了支持 Sysv 啓動腳本，還支持基於多種方式啓動或者停用服務；例如， Upstart 可以在一個特定硬件設備連接上的時候啓動一個服務。</p><p>使用 Upstart以及它原生腳本的系統替換了 /etc/inittab 文件和 /etc/init 目錄下和運行等級相關的以 .conf 作為後綴的 Sysv 啓動腳本目錄。</p><p>這些 *.conf 腳本（也稱為任務定義）通常包括以下幾部分：</p><ul><li>進程描述</li><li>進程的運行等級或者應該觸發它們的事件</li><li>應該停止進程的運行等級或者觸發停止進程的事件</li><li>選項</li><li>啓動進程的命令</li></ul><p>例如，</p><pre><code># My test service - Upstart script demo description &quot;Here goes the description of &#39;My test service&#39;&quot; author &quot;Dave Null &lt;dave.null@example.com&gt;&quot;
# Stanzas

#
# Stanzas define when and how a process is started and stopped
# See a list of stanzas here: http://upstart.ubuntu.com/wiki/Stanzas#respawn
# When to start the service
start on runlevel [2345]
# When to stop the service
stop on runlevel [016]
# Automatically restart process in case of crash
respawn
# Specify working directory
chdir /home/dave/myfiles
# Specify the process/command (add arguments if needed) to run
exec bash backup.sh arg1 arg2
</code></pre><p>要使更改生效，你要讓 upstart 重新加載它的配置文件。</p><pre><code># initctl reload-configuration
</code></pre><p>然後用下面的命令啓動你的任務。</p><pre><code>$ sudo start yourjobname
</code></pre><p>其中 yourjobname 是之前 yourjobname.conf 腳本中添加的任務名稱。</p>`,11)),e("p",null,[t[20]||(t[20]=n("關於 Upstart 更完整和詳細的介紹可以參考該項目網站的 “",-1)),i(s,{href:"http://upstart.ubuntu.com/cookbook/"},{default:p(()=>[...t[19]||(t[19]=[n("Cookbook",-1)])]),_:1}),t[21]||(t[21]=n("” 欄目。",-1))]),t[54]||(t[54]=e("h3",{id:"總結",tabindex:"-1"},[n("總結 "),e("a",{class:"header-anchor",href:"#總結","aria-label":"Permalink to “總結”"},"​")],-1)),t[55]||(t[55]=e("p",null,"瞭解 Linux 啓動進程對於你進行錯誤處理、調整計算機系統以及根據需要運行服務非常有用。",-1)),t[56]||(t[56]=e("p",null,"在這篇文章中，我們分析了你按下電源鍵啓動機器的一刻到你看到完整的可操作用户界面這段時間發生了什麼。我希望你能像我一樣把它們放在一起閲讀。歡迎在下面留下你的評論或者疑問。我們總是期待聽到讀者的回覆。",-1)),t[57]||(t[57]=e("hr",null,null,-1)),e("p",null,[t[23]||(t[23]=n("via: ",-1)),i(s,{href:"http://www.tecmint.com/linux-boot-process-and-manage-services/"},{default:p(()=>[...t[22]||(t[22]=[n("http://www.tecmint.com/linux-boot-process-and-manage-services/",-1)])]),_:1})]),e("p",null,[t[27]||(t[27]=n("作者：",-1)),i(s,{href:"http://www.tecmint.com/author/gacanepa/"},{default:p(()=>[...t[24]||(t[24]=[n("Gabriel Cánepa",-1)])]),_:1}),t[28]||(t[28]=n(" 譯者：",-1)),i(s,{href:"http://mutouxiaogui.cn/blog/"},{default:p(()=>[...t[25]||(t[25]=[n("ictlyh",-1)])]),_:1}),t[29]||(t[29]=n(" 校對：",-1)),i(s,{href:"https://github.com/wxy"},{default:p(()=>[...t[26]||(t[26]=[n("wxy",-1)])]),_:1})]),e("p",null,[t[32]||(t[32]=n("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[30]||(t[30]=[n("LCTT",-1)])]),_:1}),t[33]||(t[33]=n(" 原創翻譯，",-1)),i(s,{href:"https://linux.cn/"},{default:p(()=>[...t[31]||(t[31]=[n("Linux中國",-1)])]),_:1}),t[34]||(t[34]=n(" 榮譽推出",-1))])])}const x=o(m,[["render",u]]);export{b as __pageData,x as default};
